  3	import com.mareaalta.api.*;
  4	import com.mareaalta.infrastructure.Database;
  5	import com.mareaalta.infrastructure.RoomRepository;
  6	import io.javalin.Javalin;
  7	import io.javalin.json.JavalinJackson;
  8	
  9	public class Application {
 10	    public static void main(String[] args) throws Exception {
 11	        String dbUrl = System.getenv("DB_URL");
 12	        String dbUser = System.getenv("DB_USER");
 13	        String dbPassword = System.getenv("DB_PASSWORD");
 14	        String portStr = System.getenv("PORT");
 15	
 16	        if (dbUrl == null || dbUser == null || dbPassword == null) {
 17	            throw new RuntimeException("Variáveis de ambiente DB_URL, DB_USER, DB_PASSWORD são obrigatórias");
 18	        }
 19	
 20	        int port = portStr != null ? Integer.parseInt(portStr) : 7070;
 21	
 22	        Database.initialize(dbUrl, dbUser, dbPassword);
 23	        RoomRepository.initializeRooms();
 24	
 25	        Javalin app = Javalin.create(config -> {
 26	            config.jsonMapper(new JavalinJackson());
 27	        }).start(port);
 28	
 29	        app.get("/rooms", RoomController::getRooms);
 30	
 31	        app.post("/reservations", ReservationController::createReservation);
 32	        app.get("/reservations/{id}", ReservationController::getReservation);
 33	        app.post("/reservations/{id}/confirmation", ReservationController::confirmReservation);
 34	        app.post("/reservations/{id}/cancellation", ReservationController::cancelReservation);
 35	        app.post("/reservations/{id}/check-in", ReservationController::checkIn);
 36	        app.post("/reservations/{id}/check-out", ReservationController::checkOut);
 37	        app.get("/reservations/{id}/document", ReservationController::getDocument);
 38	
 39	        app.get("/messages", MessageController::getMessages);
 40	
 41	        app.get("/reports/occupancy", ReportController::getOccupancyReport);
 42	        app.get("/reports/revenue", ReportController::getRevenueReport);
 43	
 44	        System.out.println("Pousada Maré Alta - Sistema de Reservas iniciado na porta " + port);
 45	    }
 46	}
