 81	public class ReportController {
 82	    private static final DateTimeFormatter ISO_DATE = DateTimeFormatter.ofPattern("yyyy-MM-dd");
 83	    private static final DateTimeFormatter ISO_MONTH = DateTimeFormatter.ofPattern("yyyy-MM");
 84	
 85	    public static void getOccupancyReport(Context ctx) throws Exception {
 86	        try {
 87	            String dateStr = ctx.queryParam("date");
 88	            if (dateStr == null) {
 89	                ctx.status(400).json(errorResponse("INVALID_REQUEST", "Parâmetro date obrigatório"));
 90	                return;
 91	            }
 92	
 93	            LocalDate date = LocalDate.parse(dateStr, ISO_DATE);
 94	            String report = ReportService.generateOccupancyReport(date);
 95	
 96	            ctx.contentType("text/csv;charset=utf-8").result(report);
 97	        } catch (Exception e) {
 98	            ctx.status(400).json(errorResponse("INVALID_REQUEST", "Data inválida"));
 99	        }
100	    }
101	
102	    public static void getRevenueReport(Context ctx) throws Exception {
103	        try {
104	            String monthStr = ctx.queryParam("month");
105	            if (monthStr == null) {
106	                ctx.status(400).json(errorResponse("INVALID_REQUEST", "Parâmetro month obrigatório"));
107	                return;
108	            }
109	
110	            YearMonth ym = YearMonth.parse(monthStr, ISO_MONTH);
111	            String report = ReportService.generateRevenueReport(ym.getYear(), ym.getMonthValue());
112	
113	            ctx.contentType("text/csv;charset=utf-8").result(report);
114	        } catch (Exception e) {
115	            ctx.status(400).json(errorResponse("INVALID_REQUEST", "Mês inválido"));
116	        }
117	    }
118	
119	    private static Object errorResponse(String code, String message) {
120	        com.google.gson.JsonObject obj = new com.google.gson.JsonObject();
121	        obj.addProperty("error", code);
122	        obj.addProperty("message", message);
123	        return obj;
124	    }
125	}
126	package com.mareaalta.api;
127	
128	import com.google.gson.Gson;
129	import com.google.gson.JsonObject;
130	import com.mareaalta.domain.DocumentResponse;
131	import com.mareaalta.domain.Reservation;
132	import com.mareaalta.domain.Room;
133	import com.mareaalta.infrastructure.RoomRepository;
134	import com.mareaalta.service.DocumentGenerator;
135	import com.mareaalta.service.ReservationService;
136	import io.javalin.http.Context;
137	import java.math.BigDecimal;
138	import java.time.LocalDate;
139	import java.time.format.DateTimeFormatter;
140	
141	public class ReservationController {
142	    private static final Gson gson = new Gson();
143	    private static final DateTimeFormatter ISO_DATE = DateTimeFormatter.ofPattern("yyyy-MM-dd");
144	    private static final DateTimeFormatter BR_DATE = DateTimeFormatter.ofPattern("dd/MM/yyyy");
145	
146	    public static void createReservation(Context ctx) throws Exception {
147	        try {
148	            JsonObject body = gson.fromJson(ctx.body(), JsonObject.class);
149	
150	            if (body == null) {
151	                ctx.status(400).json(errorResponse("INVALID_REQUEST", "Corpo da requisição inválido"));
152	                return;
153	            }
154	
155	            if (!body.has("roomNumber") || !body.has("guestName") || !body.has("guestEmail") ||
156	                !body.has("checkIn") || !body.has("checkOut") || !body.has("guests") || !body.has("ratePlan")) {
157	                ctx.status(400).json(errorResponse("INVALID_REQUEST", "Campos obrigatórios faltando"));
158	                return;
159	            }
160	
161	            int roomNumber = body.get("roomNumber").getAsInt();
162	            String guestName = body.get("guestName").getAsString();
163	            String guestEmail = body.get("guestEmail").getAsString();
164	            LocalDate checkIn = LocalDate.parse(body.get("checkIn").getAsString(), ISO_DATE);
165	            LocalDate checkOut = LocalDate.parse(body.get("checkOut").getAsString(), ISO_DATE);
166	            int guests = body.get("guests").getAsInt();
167	            String ratePlan = body.get("ratePlan").getAsString();
168	
169	            if (checkOut.isBefore(checkIn) || checkOut.equals(checkIn)) {
170	                ctx.status(400).json(errorResponse("INVALID_REQUEST", "Data de saída deve ser depois da entrada"));
171	                return;
172	            }
173	
174	            // Validate identification
175	            String guestCpf = null;
176	            String companyCnpj = null;
177	            String companyName = null;
178	            String guestPassport = null;
179	            String guestCountry = null;
180	
181	            int identificationCount = 0;
182	
183	            if (body.has("guestCpf") && body.get("guestCpf").isJsonPrimitive()) {
184	                guestCpf = body.get("guestCpf").getAsString();
185	                identificationCount++;
186	            }
187	
188	            if (body.has("companyCnpj") && body.get("companyCnpj").isJsonPrimitive()) {
189	                companyCnpj = body.get("companyCnpj").getAsString();
190	                companyName = body.get("companyName").getAsString();
191	                identificationCount++;
192	            }
193	
194	            if (body.has("guestPassport") && body.get("guestPassport").isJsonPrimitive()) {
195	                guestPassport = body.get("guestPassport").getAsString();
196	                guestCountry = body.get("guestCountry").getAsString();
197	                identificationCount++;
198	            }
199	
200	            if (identificationCount != 1) {
201	                ctx.status(400).json(errorResponse("INVALID_REQUEST", "Exatamente um tipo de identificação é obrigatório"));
202	                return;
203	            }
204	
205	            Reservation reservation = ReservationService.createReservation(
206	                roomNumber, guestName, guestEmail,
207	                guestCpf, companyCnpj, companyName,
208	                guestPassport, guestCountry,
209	                checkIn, checkOut, guests, ratePlan
210	            );
211	
212	            ctx.status(201).json(serializeReservation(reservation));
213	        } catch (ReservationService.ValidationException e) {
214	            int status = e.getCode().equals("CAPACITY_EXCEEDED") ? 422 :
215	                        e.getCode().equals("ROOM_NOT_FOUND") ? 404 :
216	                        e.getCode().equals("ROOM_UNAVAILABLE") ? 409 : 400;
217	            ctx.status(status).json(errorResponse(e.getCode(), e.getMessage()));
218	        } catch (Exception e) {
219	            ctx.status(400).json(errorResponse("INVALID_REQUEST", "Erro ao processar a requisição"));
220	        }
221	    }
222	
223	    public static void getReservation(Context ctx) throws Exception {
224	        try {
225	            long id = Long.parseLong(ctx.pathParam("id"));
226	            Reservation reservation = ReservationService.getReservation(id);
227	            ctx.json(serializeReservation(reservation));
228	        } catch (ReservationService.ValidationException e) {
229	            ctx.status(404).json(errorResponse(e.getCode(), e.getMessage()));
230	        } catch (Exception e) {
231	            ctx.status(400).json(errorResponse("INVALID_REQUEST", "Erro ao processar a requisição"));
232	        }
233	    }
234	
235	    public static void confirmReservation(Context ctx) throws Exception {
236	        try {
237	            long id = Long.parseLong(ctx.pathParam("id"));
238	            JsonObject body = gson.fromJson(ctx.body(), JsonObject.class);
239	
240	            if (body == null || !body.has("amountPaid")) {
241	                ctx.status(400).json(errorResponse("INVALID_REQUEST", "Campo amountPaid obrigatório"));
242	                return;
243	            }
244	
245	            BigDecimal amountPaid = body.get("amountPaid").getAsBigDecimal();
246	            Reservation reservation = ReservationService.confirmReservation(id, amountPaid);
247	            ctx.json(serializeReservation(reservation));
248	        } catch (ReservationService.ValidationException e) {
249	            int status = e.getCode().equals("RESERVATION_NOT_FOUND") ? 404 : 409;
250	            ctx.status(status).json(errorResponse(e.getCode(), e.getMessage()));
251	        } catch (Exception e) {
252	            ctx.status(400).json(errorResponse("INVALID_REQUEST", "Erro ao processar a requisição"));
253	        }
254	    }
255	
256	    public static void checkIn(Context ctx) throws Exception {
257	        try {
258	            long id = Long.parseLong(ctx.pathParam("id"));
259	            Reservation reservation = ReservationService.checkIn(id);
260	            ctx.json(serializeReservation(reservation));
261	        } catch (ReservationService.ValidationException e) {
262	            int status = e.getCode().equals("RESERVATION_NOT_FOUND") ? 404 : 409;
263	            ctx.status(status).json(errorResponse(e.getCode(), e.getMessage()));
264	        } catch (Exception e) {
265	            ctx.status(400).json(errorResponse("INVALID_REQUEST", "Erro ao processar a requisição"));
266	        }
267	    }
268	
269	    public static void checkOut(Context ctx) throws Exception {
270	        try {
271	            long id = Long.parseLong(ctx.pathParam("id"));
272	            Reservation reservation = ReservationService.checkOut(id);
273	
274	            Room room = RoomRepository.findByNumber(reservation.getRoomNumber());
275	            String documentText = ReservationService.generateDocumentText(reservation, room);
276	
277	            DocumentResponse doc = buildDocumentResponse(reservation, room, documentText);
278	            ctx.json(doc);
279	        } catch (ReservationService.ValidationException e) {
280	            int status = e.getCode().equals("RESERVATION_NOT_FOUND") ? 404 : 409;
281	            ctx.status(status).json(errorResponse(e.getCode(), e.getMessage()));
282	        } catch (Exception e) {
283	            ctx.status(400).json(errorResponse("INVALID_REQUEST", "Erro ao processar a requisição"));
284	        }
285	    }
286	
287	    public static void cancelReservation(Context ctx) throws Exception {
288	        try {
289	            long id = Long.parseLong(ctx.pathParam("id"));
290	            Reservation reservation = ReservationService.cancelReservation(id);
291	            ctx.json(serializeReservation(reservation));
292	        } catch (ReservationService.ValidationException e) {
293	            int status = e.getCode().equals("RESERVATION_NOT_FOUND") ? 404 : 409;
294	            ctx.status(status).json(errorResponse(e.getCode(), e.getMessage()));
295	        } catch (Exception e) {
296	            ctx.status(400).json(errorResponse("INVALID_REQUEST", "Erro ao processar a requisição"));
297	        }
298	    }
299	
300	    public static void getDocument(Context ctx) throws Exception {
301	        try {
302	            long id = Long.parseLong(ctx.pathParam("id"));
303	            Reservation reservation = ReservationService.getReservation(id);
304	
305	            if (reservation.getStatus() == Reservation.Status.PENDING) {
306	                ctx.status(409).json(errorResponse("OPERATION_NOT_ALLOWED", "Documento não disponível para reserva pendente"));
307	                return;
308	            }
309	
310	            Room room = RoomRepository.findByNumber(reservation.getRoomNumber());
311	            String documentText = ReservationService.generateDocumentText(reservation, room);
312	
313	            DocumentResponse doc = buildDocumentResponse(reservation, room, documentText);
314	            ctx.json(doc);
315	        } catch (ReservationService.ValidationException e) {
316	            ctx.status(404).json(errorResponse(e.getCode(), e.getMessage()));
317	        } catch (Exception e) {
318	            ctx.status(400).json(errorResponse("INVALID_REQUEST", "Erro ao processar a requisição"));
319	        }
320	    }
321	
322	    private static JsonObject serializeReservation(Reservation res) {
323	        JsonObject obj = new JsonObject();
324	        obj.addProperty("id", res.getId());
325	        obj.addProperty("roomNumber", res.getRoomNumber());
326	        obj.addProperty("guestName", res.getGuestName());
327	        obj.addProperty("guestEmail", res.getGuestEmail());
328	        obj.addProperty("guestCpf", res.getGuestCpf());
329	        obj.addProperty("companyCnpj", res.getCompanyCnpj());
330	        obj.addProperty("companyName", res.getCompanyName());
331	        obj.addProperty("guestPassport", res.getGuestPassport());
332	        obj.addProperty("guestCountry", res.getGuestCountry());
333	        obj.addProperty("checkIn", res.getCheckIn().format(ISO_DATE));
334	        obj.addProperty("checkOut", res.getCheckOut().format(ISO_DATE));
335	        obj.addProperty("guests", res.getGuests());
336	        obj.addProperty("ratePlan", res.getRatePlan().name());
337	        obj.addProperty("nights", res.getNights());
338	        obj.addProperty("subtotal", res.getSubtotal().doubleValue());
339	        obj.addProperty("discount", res.getDiscount() != null ? res.getDiscount().doubleValue() : null);
340	        obj.addProperty("total", res.getTotal().doubleValue());
341	        obj.addProperty("status", res.getStatus().name());
342	        obj.addProperty("amountPaid", res.getAmountPaid().doubleValue());
343	        obj.addProperty("refund", res.getRefund() != null ? res.getRefund().doubleValue() : null);
344	        return obj;
345	    }
346	
347	    private static DocumentResponse buildDocumentResponse(Reservation res, Room room, String text) {
348	        String title = res.getGuestCpf() != null ? "Comprovante de reserva" :
349	                      res.getCompanyCnpj() != null ? "Fatura de hospedagem" : "Booking receipt";
350	
351	        return new DocumentResponse(
352	            title, res.getId(), res.getGuestName(),
353	            res.getGuestCpf(), res.getCompanyCnpj(), res.getCompanyName(),
354	            res.getGuestPassport(), res.getGuestCountry(),
355	            res.getRoomNumber(), room.getType().name(),
356	            res.getCheckIn().format(BR_DATE), res.getCheckOut().format(BR_DATE),
357	            res.getNights(), res.getSubtotal(), res.getDiscount(), res.getTotal(),
358	            text
359	        );
360	    }
361	
362	    private static JsonObject errorResponse(String code, String message) {
363	        JsonObject obj = new JsonObject();
364	        obj.addProperty("error", code);
365	        obj.addProperty("message", message);
366	        return obj;
367	    }
368	}
