165	            LocalDate checkOut = LocalDate.parse(body.get("checkOut").getAsString(), ISO_DATE);
166	            int guests = body.get("guests").getAsInt();
167	            String ratePlan = body.get("ratePlan").getAsString();
168	
169	            if (checkOut.isBefore(checkIn) || checkOut.equals(checkIn)) {
170	                ctx.status(400).json(errorResponse("INVALID_REQUEST", "Data de saída deve ser depois da entrada"));
171	                return;
172	            }
173	
174	            // Validate identification
175	            String guestCpf = null;
176	            String companyCnpj = null;
177	            String companyName = null;
178	            String guestPassport = null;
179	            String guestCountry = null;
180	
181	            int identificationCount = 0;
182	
183	            if (body.has("guestCpf") && body.get("guestCpf").isJsonPrimitive()) {
184	                guestCpf = body.get("guestCpf").getAsString();
185	                identificationCount++;
186	            }
187	
188	            if (body.has("companyCnpj") && body.get("companyCnpj").isJsonPrimitive()) {
189	                companyCnpj = body.get("companyCnpj").getAsString();
