196	                guestCountry = body.get("guestCountry").getAsString();
197	                identificationCount++;
198	            }
199	
200	            if (identificationCount != 1) {
201	                ctx.status(400).json(errorResponse("INVALID_REQUEST", "Exatamente um tipo de identificação é obrigatório"));
202	                return;
203	            }
204	
205	            Reservation reservation = ReservationService.createReservation(
206	                roomNumber, guestName, guestEmail,
207	                guestCpf, companyCnpj, companyName,
208	                guestPassport, guestCountry,
209	                checkIn, checkOut, guests, ratePlan
