 90	    private static String formatCurrency(BigDecimal value) {
 91	        String formatted = String.format("%.2f", value);
 92	        String[] parts = formatted.split("\\.");
 93	        String intPart = parts[0];
 94	        String decPart = parts[1];
 95	
 96	        StringBuilder result = new StringBuilder();
 97	        int length = intPart.length();
 98	        for (int i = 0; i < length; i++) {
 99	            if (i > 0 && (length - i) % 3 == 0) {
100	                result.append(".");
101	            }
102	            result.append(intPart.charAt(i));
103	        }
104	
105	        return "R$ " + result.toString() + "," + decPart;
106	    }
