114	import java.math.BigDecimal;
115	import java.math.RoundingMode;
116	import java.time.LocalDate;
117	
118	public class PricingService {
119	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
120	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = new BigDecimal("0.15");
121	
122	    public static boolean isHighSeason(LocalDate date) {
123	        int month = date.getMonthValue();
124	        int day = date.getDayOfMonth();
125	
126	        return (month == 7) ||
127	               (month == 12 && day >= 15) ||
128	               (month == 1) ||
129	               (month == 2);
130	    }
131	
132	    public static BigDecimal getNightlyRate(BigDecimal baseRate, LocalDate date) {
133	        if (isHighSeason(date)) {
134	            return baseRate.multiply(HIGH_SEASON_MULTIPLIER).setScale(2, RoundingMode.HALF_EVEN);
135	        }
136	        return baseRate.setScale(2, RoundingMode.HALF_EVEN);
137	    }
138	
139	    public static BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
140	        BigDecimal subtotal = BigDecimal.ZERO;
141	        LocalDate current = checkIn;
142	
143	        while (current.isBefore(checkOut)) {
144	            BigDecimal nightlyRate = getNightlyRate(baseRate, current);
145	            subtotal = subtotal.add(nightlyRate);
146	            current = current.plusDays(1);
147	        }
148	
149	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
150	    }
151	
152	    public static BigDecimal calculateDiscount(BigDecimal subtotal, String ratePlan) {
153	        if ("NON_REFUNDABLE".equals(ratePlan)) {
154	            return subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE).setScale(2, RoundingMode.HALF_EVEN);
155	        }
156	        return BigDecimal.ZERO;
157	    }
158	
159	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
160	        return subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
161	    }
162	
163	    public static int countNights(LocalDate checkIn, LocalDate checkOut) {
164	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
165	    }
166	}
