182	    public static String generateOccupancyReport(LocalDate date) throws SQLException {
183	        List<Room> allRooms = RoomRepository.findAll();
184	        Map<Integer, Reservation> occupiedRooms = new HashMap<>();
185	
186	        for (Room room : allRooms) {
187	            List<Reservation> reservations = ReservationRepository.findByRoomAndDate(room.getNumber(), date);
188	            if (!reservations.isEmpty()) {
189	                occupiedRooms.put(room.getNumber(), reservations.get(0));
190	            }
191	        }
192	
193	        StringBuilder csv = new StringBuilder();
194	        csv.append("room,type,reservation,check_in,check_out\n");
195	
196	        for (Room room : allRooms) {
197	            if (occupiedRooms.containsKey(room.getNumber())) {
198	                Reservation res = occupiedRooms.get(room.getNumber());
199	                csv.append(room.getNumber()).append(",")
200	                   .append(room.getType()).append(",")
201	                   .append(res.getId()).append(",")
202	                   .append(res.getCheckIn().format(ISO_DATE)).append(",")
203	                   .append(res.getCheckOut().format(ISO_DATE)).append("\n");
204	            }
205	        }
206	
207	        csv.append("total,").append(occupiedRooms.size()).append("/").append(allRooms.size()).append("\n");
208	
209	        return csv.toString();
210	    }
