212	    public static String generateRevenueReport(int year, int month) throws SQLException {
213	        List<Reservation> reservations = ReservationRepository.findByMonthStarting(year, month);
214	
215	        StringBuilder csv = new StringBuilder();
216	        csv.append("reservation,room,check_in,check_out,status,amount\n");
217	
218	        BigDecimal total = BigDecimal.ZERO;
219	
220	        for (Reservation res : reservations) {
221	            BigDecimal amount = calculateRevenueAmount(res);
222	            total = total.add(amount);
223	
224	            csv.append(res.getId()).append(",")
225	               .append(res.getRoomNumber()).append(",")
226	               .append(res.getCheckIn().format(ISO_DATE)).append(",")
227	               .append(res.getCheckOut().format(ISO_DATE)).append(",")
228	               .append(res.getStatus()).append(",")
229	               .append(formatDecimal(amount)).append("\n");
230	        }
231	
232	        csv.append("total,,,,").append(formatDecimal(total)).append("\n");
233	
234	        return csv.toString();
235	    }
236	
237	    private static BigDecimal calculateRevenueAmount(Reservation reservation) {
238	        if (reservation.getStatus() == Reservation.Status.CANCELLED) {
239	            if (reservation.getRefund() == null) {
240	                return BigDecimal.ZERO;
241	            }
242	            return reservation.getAmountPaid().subtract(reservation.getRefund());
243	        }
244	
245	        if (reservation.getStatus() == Reservation.Status.PENDING) {
246	            return BigDecimal.ZERO;
247	        }
248	
249	        return reservation.getAmountPaid();
250	    }
251	
252	    private static String formatDecimal(BigDecimal value) {
253	        return String.format("%.2f", value);
254	    }
