223	    public static void initialize(String url, String user, String password) throws SQLException {
224	        dbUrl = url;
225	        dbUser = user;
226	        dbPassword = password;
227	        connection = DriverManager.getConnection(dbUrl, dbUser, dbPassword);
228	        createSchema();
229	    }
