238	    private static void createSchema() throws SQLException {
239	        String[] schemas = {
240	            createRoomsTable(),
241	            createReservationsTable(),
242	            createMessagesTable()
243	        };
244	
245	        try (Statement stmt = connection.createStatement()) {
246	            for (String schema : schemas) {
247	                stmt.execute(schema);
248	            }
249	        }
