217	public class Database {
218	    private static Connection connection;
219	    private static String dbUrl;
220	    private static String dbUser;
221	    private static String dbPassword;
222	
223	    public static void initialize(String url, String user, String password) throws SQLException {
224	        dbUrl = url;
225	        dbUser = user;
226	        dbPassword = password;
227	        connection = DriverManager.getConnection(dbUrl, dbUser, dbPassword);
228	        createSchema();
229	    }
230	
231	    public static Connection getConnection() throws SQLException {
232	        if (connection == null || connection.isClosed()) {
233	            connection = DriverManager.getConnection(dbUrl, dbUser, dbPassword);
234	        }
235	        return connection;
236	    }
237	
238	    private static void createSchema() throws SQLException {
239	        String[] schemas = {
240	            createRoomsTable(),
241	            createReservationsTable(),
242	            createMessagesTable()
243	        };
244	
245	        try (Statement stmt = connection.createStatement()) {
246	            for (String schema : schemas) {
247	                stmt.execute(schema);
248	            }
249	        }
250	    }
251	
252	    private static String createRoomsTable() {
253	        return """
254	            CREATE TABLE IF NOT EXISTS rooms (
255	                number INTEGER PRIMARY KEY,
256	                type VARCHAR(50) NOT NULL,
257	                capacity INTEGER NOT NULL,
258	                nightly_rate NUMERIC(10, 2) NOT NULL
259	            );
260	            """;
261	    }
262	
263	    private static String createReservationsTable() {
264	        return """
265	            CREATE TABLE IF NOT EXISTS reservations (
266	                id SERIAL PRIMARY KEY,
267	                room_number INTEGER NOT NULL REFERENCES rooms(number),
268	                guest_name VARCHAR(255) NOT NULL,
269	                guest_email VARCHAR(255) NOT NULL,
270	                guest_cpf VARCHAR(20),
271	                company_cnpj VARCHAR(20),
272	                company_name VARCHAR(255),
273	                guest_passport VARCHAR(50),
274	                guest_country VARCHAR(100),
275	                check_in DATE NOT NULL,
276	                check_out DATE NOT NULL,
277	                guests INTEGER NOT NULL,
278	                rate_plan VARCHAR(50) NOT NULL,
279	                nights INTEGER NOT NULL,
280	                subtotal NUMERIC(10, 2) NOT NULL,
281	                discount NUMERIC(10, 2),
282	                total NUMERIC(10, 2) NOT NULL,
283	                status VARCHAR(50) NOT NULL,
284	                amount_paid NUMERIC(10, 2) DEFAULT 0,
285	                refund NUMERIC(10, 2),
286	                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
287	            );
288	            """;
289	    }
290	
291	    private static String createMessagesTable() {
292	        return """
293	            CREATE TABLE IF NOT EXISTS messages (
294	                id SERIAL PRIMARY KEY,
295	                channel VARCHAR(50) NOT NULL,
296	                "to" VARCHAR(255) NOT NULL,
297	                subject VARCHAR(255) NOT NULL,
298	                body TEXT NOT NULL,
299	                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
300	            );
301	            """;
302	    }
303	}
