313	            INSERT INTO messages (channel, "to", subject, body)
314	            VALUES (?, ?, ?, ?)
315	            """;
316	
317	        try (Connection conn = Database.getConnection();
318	             PreparedStatement pstmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
319	            pstmt.setString(1, message.getChannel());
320	            pstmt.setString(2, message.getTo());
321	            pstmt.setString(3, message.getSubject());
