427	        String sql = """
428	            SELECT COUNT(*) FROM reservations
429	            WHERE room_number = ?
430	            AND status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT')
431	            AND check_in < ? AND check_out > ?
