456	        List<Reservation> reservations = new ArrayList<>();
457	        try (Connection conn = Database.getConnection();
458	             PreparedStatement pstmt = conn.prepareStatement(sql)) {
459	            pstmt.setInt(1, roomNumber);
460	            pstmt.setDate(2, java.sql.Date.valueOf(date));
